solution.solution.cpp:
#include <map>
#include <set>
#include <string>
#include <vector>

static void visit(const std::map<std::string, std::vector<std::string>>& imports, const std::string& module,
                  std::set<std::string>& started, std::vector<std::string>& order)
{
    if (!started.insert(module).second) return;
    const auto it{ imports.find(module) };
    if (it != imports.end())
        for (const std::string& dependency : it->second) visit(imports, dependency, started, order);
    order.push_back(module);
}

std::vector<std::string> loadOrder(const std::map<std::string, std::vector<std::string>>& imports, const std::string& root)
{
    std::vector<std::string> order;
    std::set<std::string> started;
    visit(imports, root, started, order);
    return order;
}

unitTests:
using Graph = std::map<std::string, std::vector<std::string>>;
using Names = std::vector<std::string>;
TEST("the example") {
    const Graph g{ {"game.exe", {"audio.dll", "physics.dll"}}, {"audio.dll", {"math.dll", "kernel32.dll"}}, {"physics.dll", {"math.dll"}}, {"math.dll", {"kernel32.dll"}} };
    CHECK_EQ(loadOrder(g, "game.exe"), (Names{ "kernel32.dll", "math.dll", "audio.dll", "physics.dll", "game.exe" }));
}
TEST("no imports at all") { CHECK_EQ(loadOrder(Graph{}, "tool.exe"), (Names{ "tool.exe" })); }
TEST("a chain") { CHECK_EQ(loadOrder(Graph{ {"a.exe", {"b.dll"}}, {"b.dll", {"c.dll"}} }, "a.exe"), (Names{ "c.dll", "b.dll", "a.exe" })); }
TEST("listed order matters") { CHECK_EQ(loadOrder(Graph{ {"a.exe", {"z.dll", "y.dll"}} }, "a.exe"), (Names{ "z.dll", "y.dll", "a.exe" })); }
TEST("a loop does not hang") { CHECK_EQ(loadOrder(Graph{ {"a.exe", {"x.dll"}}, {"x.dll", {"y.dll"}}, {"y.dll", {"x.dll"}} }, "a.exe"), (Names{ "y.dll", "x.dll", "a.exe" })); }
TEST("shared dependency once") { CHECK_EQ(loadOrder(Graph{ {"a.exe", {"p.dll", "q.dll"}}, {"p.dll", {"s.dll"}}, {"q.dll", {"s.dll"}} }, "a.exe"), (Names{ "s.dll", "p.dll", "q.dll", "a.exe" })); }

